const AudioContext = window.AudioContext || window.webkitAudioContext;
        let audioCtx = null;
        let oscillator = null;
        let gainNode = null;
        let isPlaying = false;
        let animationId = null;
        let testType = '';

        const canvas = document.getElementById('waveform');
        const ctx = canvas.getContext('2d');
        canvas.width = canvas.offsetWidth * 2;
        canvas.height = 400;

        document.getElementById('test-volume').addEventListener('input', (e) => {
            document.getElementById('volume-display').textContent = e.target.value + '%';
            if (gainNode) gainNode.gain.value = e.target.value / 100 * 0.5;
        });

        function initAudio() {
            if (!audioCtx) audioCtx = new AudioContext();
            if (audioCtx.state === 'suspended') audioCtx.resume();
            gainNode = audioCtx.createGain();
            gainNode.gain.value = document.getElementById('test-volume').value / 100 * 0.5;
            gainNode.connect(audioCtx.destination);
        }

        function runTest(type) {
            stopTest();
            initAudio();
            isPlaying = true;
            testType = type;
            document.getElementById('stop-btn').classList.remove('hidden');
            document.getElementById('status-badge').classList.remove('hidden');

            if (type === 'sweep') {
                document.getElementById('test-info').textContent = 'Playing frequency sweep: 20Hz  to  20kHz';
                sweepTest();
            } else if (type === 'impulse') {
                document.getElementById('test-info').textContent = 'Playing impulse test...';
                impulseTest();
            } else if (type === 'pink') {
                document.getElementById('test-info').textContent = 'Playing pink noise...';
                pinkNoiseTest();
            } else if (type === 'sine') {
                document.getElementById('test-info').textContent = 'Playing 1kHz sine wave reference';
                sineTest(1000);
            }
            drawWave();
        }

        function sweepTest() {
            oscillator = audioCtx.createOscillator();
            oscillator.type = 'sine';
            const startFreq = 20;
            const endFreq = 20000;
            const duration = 10;
            oscillator.frequency.setValueAtTime(startFreq, audioCtx.currentTime);
            oscillator.frequency.exponentialRampToValueAtTime(endFreq, audioCtx.currentTime + duration);
            oscillator.connect(gainNode);
            oscillator.start();
            oscillator.stop(audioCtx.currentTime + duration);
            setTimeout(stopTest, duration * 1000);
        }

        function impulseTest() {
            const bufferSize = audioCtx.sampleRate * 0.5;
            const buffer = audioCtx.createBuffer(1, bufferSize, audioCtx.sampleRate);
            const data = buffer.getChannelData(0);
            for (let i = 0; i < 100; i++) {
                data[i] = Math.random() * 2 - 1;
            }
            for (let i = 100; i < bufferSize; i++) {
                data[i] = 0;
            }
            const source = audioCtx.createBufferSource();
            source.buffer = buffer;
            source.connect(gainNode);
            source.start();
            source.stop(audioCtx.currentTime + 0.5);
            setTimeout(stopTest, 600);
        }

        function pinkNoiseTest() {
            const bufferSize = audioCtx.sampleRate * 5;
            const buffer = audioCtx.createBuffer(1, bufferSize, audioCtx.sampleRate);
            const data = buffer.getChannelData(0);
            let b0 = 0, b1 = 0, b2 = 0, b3 = 0, b4 = 0, b5 = 0, b6 = 0;
            for (let i = 0; i < bufferSize; i++) {
                const white = Math.random() * 2 - 1;
                b0 = 0.99886 * b0 + white * 0.0555179;
                b1 = 0.99332 * b1 + white * 0.0750759;
                b2 = 0.96900 * b2 + white * 0.1538520;
                b3 = 0.86650 * b3 + white * 0.3104856;
                b4 = 0.55000 * b4 + white * 0.5329522;
                b5 = -0.7616 * b5 - white * 0.0168980;
                data[i] = (b0 + b1 + b2 + b3 + b4 + b5 + b6 + white * 0.5362) * 0.11;
                b6 = white * 0.115926;
            }
            const source = audioCtx.createBufferSource();
            source.buffer = buffer;
            source.connect(gainNode);
            source.start();
            source.stop(audioCtx.currentTime + 5);
            setTimeout(stopTest, 5100);
        }

        function sineTest(freq) {
            oscillator = audioCtx.createOscillator();
            oscillator.type = 'sine';
            oscillator.frequency.value = freq;
            oscillator.connect(gainNode);
            oscillator.start();
        }

        function stopTest() {
            isPlaying = false;
            if (oscillator) {
                oscillator.stop();
                oscillator.disconnect();
                oscillator = null;
            }
            if (animationId) {
                cancelAnimationFrame(animationId);
                animationId = null;
            }
            ctx.clearRect(0, 0, canvas.width, canvas.height);
            document.getElementById('stop-btn').classList.add('hidden');
            document.getElementById('status-badge').classList.add('hidden');
            document.getElementById('test-info').textContent = 'Select a test to begin';
        }

        function drawWave() {
            if (!isPlaying) return;
            const analyser = audioCtx.createAnalyser();
            gainNode.disconnect();
            gainNode.connect(analyser);
            analyser.connect(audioCtx.destination);
            analyser.fftSize = 2048;
            const bufferLength = analyser.frequencyBinCount;
            const dataArray = new Uint8Array(bufferLength);

            function draw() {
                if (!isPlaying) return;
                animationId = requestAnimationFrame(draw);
                analyser.getByteTimeDomainData(dataArray);
                ctx.fillStyle = '#1e1b4b';
                ctx.fillRect(0, 0, canvas.width, canvas.height);
                ctx.lineWidth = 3;
                ctx.strokeStyle = testType === 'sweep' ? '#06b6d4' : testType === 'impulse' ? '#8b5cf6' : testType === 'pink' ? '#ec4899' : '#f59e0b';
                ctx.beginPath();
                const sliceWidth = canvas.width / bufferLength;
                let x = 0;
                for (let i = 0; i < bufferLength; i++) {
                    const v = dataArray[i] / 128.0;
                    const y = v * canvas.height / 2;
                    if (i === 0) ctx.moveTo(x, y);
                    else ctx.lineTo(x, y);
                    x += sliceWidth;
                }
                ctx.lineTo(canvas.width, canvas.height / 2);
                ctx.stroke();
            }
            draw();
        }
